            pass
    # Locate horizontal repeated rows of the palette bar.
    for r in range(h):
        cols = [c for c,v in enumerate(g[r]) if v]
        if len(cols) >= 2:
            seq = [g[r][c] for c in cols]
            end = r
            while end + 1 < h and [g[end+1][c] for c in cols] == seq:
                end += 1
            if end-r+1 >= 2:
                strip = (r, end, cols, seq)
                break
    if strip is None:
        return g
    sr, er, cols, palette = strip
    # The stencil is the repeated nonzero object other than the palette bar.
    occupied = [(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] and not (sr <= r <= er and c in cols)]
    # Find the compact object bounds (all object cells share its current color).
    if not occupied:
        return g
