    minc,maxc=min(c for r,c in cells),max(c for r,c in cells)
    stencil={(r-minr,c-minc) for r,c in cells}
    # Stack palette-colored copies in order; the original-color copy is the anchor.
    try:
        anchor = palette.index(color)
