 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find a palette bar repeated on adjacent rows or columns.
    palette = bar_cells = None
    for r in range(h - 1):
        cols = [c for c, v in enumerate(g[r]) if v]
        if len(cols) >= 2 and all(g[r+1][c] == g[r][c] for c in cols):
            # maximal run of rows carrying this palette
            end = r + 1
            while end + 1 < h and all(g[end+1][c] == g[r][c] for c in cols):
                end += 1
            palette = [g[r][c] for c in cols]
            bar_cells = {(rr, c) for rr in range(r, end+1) for c in cols}
            break
    if palette is None:
        for c in range(w - 1):
            rows = [r for r in range(h) if g[r][c]]
            if len(rows) >= 2 and all(g[r][c+1] == g[r][c] for r in rows):
                end = c + 1
                while end + 1 < w and all(g[r][end+1] == g[r][c] for r in rows):
                    end += 1
                palette = [g[r][c] for r in rows]
                bar_cells = {(r, cc) for cc in range(c, end+1) for r in rows}
                break
    if not palette:
        return g
    # The palette entry already present in the target stencil identifies it.
    anchor_color = next((v for v in palette if any(g[r][c] == v and (r,c) not in bar_cells for r in range(h) for c in range(w))), None)
    if anchor_color is None:
        return g
    pts = [(r,c) for r in range(h) for c in range(w) if g[r][c] == anchor_color and (r,c) not in bar_cells]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    mask={(r-r0,c-c0) for r,c in pts}
    step=r1-r0+1
    anchor=palette.index(anchor_color)
    start=r0-anchor*step
    # Erase palette bar and draw one translated stencil for each palette color.
    for r,c in bar_cells:
        g[r][c]=0
    for i,col in enumerate(palette):
        top=start+i*step
        for dr,dc in mask:
            rr,cc=top+dr,c0+dc
            if 0<=rr<h and 0<=cc<w:
                g[rr][cc]=col
    return g

